  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  DATA_TYPE eps = SCALAR_VAL(0.1);

#pragma scop

  /* Step 1: Calculate mean via loop interchange for sequential memory access */
  for (j = 0; j < _PB_M; j++) {
    mean[j] = SCALAR_VAL(0.0);
  }

  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < _PB_M; j++) {
      mean[j] += data[i][j];
    }
  }

  DATA_TYPE float_n_inv = SCALAR_VAL(1.0) / float_n;
  for (j = 0; j < _PB_M; j++) {
    mean[j] *= float_n_inv;
    stddev[j] = SCALAR_VAL(0.0);
  }

  /* Step 2: Calculate stddev, maintaining the efficient interleaved layout */
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < _PB_M; j++) {
      DATA_TYPE diff = data[i][j] - mean[j];
      stddev[j] += diff * diff;
    }
  }

  for (j = 0; j < _PB_M; j++) {
    stddev[j] *= float_n_inv;
    stddev[j] = SQRT_FUN(stddev[j]);
    stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
  }

  /* 
   * Pre-allocate memory to perform a transpose on the dataset. 
   * A 1D flattening is used to guarantee simple indexing for the compiler.
   */
  DATA_TYPE* dataT = (DATA_TYPE*)malloc(sizeof(DATA_TYPE) * (size_t)_PB_M * (size_t)_PB_N);
  DATA_TYPE sqrt_n = SQRT_FUN(float_n);

  if (dataT) {
    /* Step 3: Fused centering, reducing, and cache-blocked transposition */
    int TILE = 64;
    for (j = 0; j < _PB_M; j += TILE) {
        int j_max = (j + TILE < _PB_M) ? j + TILE : _PB_M;
        DATA_TYPE div_tile[64];

        // Cache divisions specifically for the current column slice
        for (int jj = j; jj < j_max; jj++) {
            div_tile[jj - j] = sqrt_n * stddev[jj];
        }

        for (i = 0; i < _PB_N; i += TILE) {
            int i_max = (i + TILE < _PB_N) ? i + TILE : _PB_N;
            for (int ii = i; ii < i_max; ii++) {
                for (int jj = j; jj < j_max; jj++) {
                    DATA_TYPE val = data[ii][jj];
                    val -= mean[jj];
                    val /= div_tile[jj - j];

                    data[ii][jj] = val;
                    dataT[jj * _PB_N + ii] = val; // Store transposed
                }
            }
        }
    }

    /* Step 4: Block-tiled symmetric matrix multiplication using transposed array */
    int BLOCK_I = 64;
    int BLOCK_J = 64;
    for (int i_b = 0; i_b < _PB_M - 1; i_b += BLOCK_I) {
        for (int j_b = i_b; j_b < _PB_M; j_b += BLOCK_J) {
            int i_max = (i_b + BLOCK_I < _PB_M - 1) ? i_b + BLOCK_I : _PB_M - 1;
            int j_max = (j_b + BLOCK_J < _PB_M) ? j_b + BLOCK_J : _PB_M;

            for (i = i_b; i < i_max; i++) {
                int j_start = (i_b == j_b) ? i + 1 : j_b;
                j = j_start;

                // Aggressive manual loop unrolling enables tight register packing and pipeline saturation
                for (; j <= j_max - 8; j += 8) {
                    DATA_TYPE sum0 = SCALAR_VAL(0.0), sum1 = SCALAR_VAL(0.0), 
                              sum2 = SCALAR_VAL(0.0), sum3 = SCALAR_VAL(0.0),
                              sum4 = SCALAR_VAL(0.0), sum5 = SCALAR_VAL(0.0), 
                              sum6 = SCALAR_VAL(0.0), sum7 = SCALAR_VAL(0.0);

                    DATA_TYPE* row_i  = &dataT[i * _PB_N];
                    DATA_TYPE* row_j0 = &dataT[(j + 0) * _PB_N];
                    DATA_TYPE* row_j1 = &dataT[(j + 1) * _PB_N];
                    DATA_TYPE* row_j2 = &dataT[(j + 2) * _PB_N];
                    DATA_TYPE* row_j3 = &dataT[(j + 3) * _PB_N];
                    DATA_TYPE* row_j4 = &dataT[(j + 4) * _PB_N];
                    DATA_TYPE* row_j5 = &dataT[(j + 5) * _PB_N];
                    DATA_TYPE* row_j6 = &dataT[(j + 6) * _PB_N];
                    DATA_TYPE* row_j7 = &dataT[(j + 7) * _PB_N];

                    for (k = 0; k < _PB_N; k++) {
                        DATA_TYPE vi = row_i[k];
                        sum0 += vi * row_j0[k];
                        sum1 += vi * row_j1[k];
                        sum2 += vi * row_j2[k];
                        sum3 += vi * row_j3[k];
                        sum4 += vi * row_j4[k];
                        sum5 += vi * row_j5[k];
                        sum6 += vi * row_j6[k];
                        sum7 += vi * row_j7[k];
                    }

                    corr[i][j + 0] = sum0; corr[j + 0][i] = sum0;
                    corr[i][j + 1] = sum1; corr[j + 1][i] = sum1;
                    corr[i][j + 2] = sum2; corr[j + 2][i] = sum2;
                    corr[i][j + 3] = sum3; corr[j + 3][i] = sum3;
                    corr[i][j + 4] = sum4; corr[j + 4][i] = sum4;
                    corr[i][j + 5] = sum5; corr[j + 5][i] = sum5;
                    corr[i][j + 6] = sum6; corr[j + 6][i] = sum6;
                    corr[i][j + 7] = sum7; corr[j + 7][i] = sum7;
                }

                // Secondary 4-unroll for the loop remainder 
                for (; j <= j_max - 4; j += 4) {
                    DATA_TYPE sum0 = SCALAR_VAL(0.0), sum1 = SCALAR_VAL(0.0), 
                              sum2 = SCALAR_VAL(0.0), sum3 = SCALAR_VAL(0.0);

                    DATA_TYPE* row_i  = &dataT[i * _PB_N];
                    DATA_TYPE* row_j0 = &dataT[(j + 0) * _PB_N];
                    DATA_TYPE* row_j1 = &dataT[(j + 1) * _PB_N];
                    DATA_TYPE* row_j2 = &dataT[(j + 2) * _PB_N];
                    DATA_TYPE* row_j3 = &dataT[(j + 3) * _PB_N];

                    for (k = 0; k < _PB_N; k++) {
                        DATA_TYPE vi = row_i[k];
                        sum0 += vi * row_j0[k];
                        sum1 += vi * row_j1[k];
                        sum2 += vi * row_j2[k];
                        sum3 += vi * row_j3[k];
                    }

                    corr[i][j + 0] = sum0; corr[j + 0][i] = sum0;
                    corr[i][j + 1] = sum1; corr[j + 1][i] = sum1;
                    corr[i][j + 2] = sum2; corr[j + 2][i] = sum2;
                    corr[i][j + 3] = sum3; corr[j + 3][i] = sum3;
                }

                // Tertiary unroll bounds fallback
                for (; j < j_max; j++) {
                    DATA_TYPE sum = SCALAR_VAL(0.0);
                    DATA_TYPE* row_i = &dataT[i * _PB_N];
                    DATA_TYPE* row_j = &dataT[j * _PB_N];
                    for (k = 0; k < _PB_N; k++) {
                        sum += row_i[k] * row_j[k];
                    }
                    corr[i][j] = sum;
                    corr[j][i] = sum;
                }
            }
        }
    }

    // Construct identity 1.0 main diagonal safely at the end
    for (i = 0; i < _PB_M; i++) {
        corr[i][i] = SCALAR_VAL(1.0);
    }

    free(dataT);
  } else {
    /* Fallback strategy should the internal contiguous data allocation fail */
    for (j = 0; j < _PB_M; j += 64) {
        int j_max = (j + 64 < _PB_M) ? j + 64 : _PB_M;
        DATA_TYPE div_tile[64];
        for (int jj = j; jj < j_max; jj++) {
            div_tile[jj - j] = sqrt_n * stddev[jj];
        }
        for (i = 0; i < _PB_N; i++) {
            for (int jj = j; jj < j_max; jj++) {
                data[i][jj] -= mean[jj];
                data[i][jj] /= div_tile[jj - j];
            }
        }
    }

    for (i = 0; i < _PB_M; i++) {
        for (j = i; j < _PB_M; j++) {
            corr[i][j] = SCALAR_VAL(0.0);
        }
        corr[i][i] = SCALAR_VAL(1.0);
    }

    // Matrix cache-block fallback using sequential dot product without transposition overrides
    int BLK = 32;
    for (int i_b = 0; i_b < _PB_M - 1; i_b += BLK) {
        for (int j_b = i_b; j_b < _PB_M; j_b += BLK) {
            int i_max = (i_b + BLK < _PB_M - 1) ? i_b + BLK : _PB_M - 1;
            int j_max = (j_b + BLK < _PB_M) ? j_b + BLK : _PB_M;

            for (k = 0; k < _PB_N; k++) {
                if (i_b == j_b) {
                    for (i = i_b; i < i_max; i++) {
                        DATA_TYPE d0 = data[k][i];
                        for (j = i + 1; j < j_max; j++) {
                            corr[i][j] += d0 * data[k][j];
                        }
                    }
                } else {
                    for (i = i_b; i < i_max; i++) {
                        DATA_TYPE d0 = data[k][i];
                        for (j = j_b; j < j_max; j++) {
                            corr[i][j] += d0 * data[k][j];
                        }
                    }
                }
            }
        }
    }

    // Reflect upper triangular blocks onto bottom triangular structure
    for (i = 0; i < _PB_M - 1; i++) {
        for (j = i + 1; j < _PB_M; j++) {
            corr[j][i] = corr[i][j];
        }
    }
  }

#pragma endscop
}


