  #pragma omp parallel for schedule(static)
  for (int jj = 0; jj < _PB_M; jj += CHUNK) {
      int j_max = (jj + CHUNK < _PB_M) ? jj + CHUNK : _PB_M;

      // Compute mean for the chunk
      for (int j = jj; j < j_max; j++) {
