      for (int j = jj; j < j_max; j++) {
          mean[j] /= float_n;
      }

      // Compute standard deviation for the chunk
      for (int j = jj; j < j_max; j++) {
          stddev[j] = SCALAR_VAL(0.0);
      }
      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              DATA_TYPE diff = data[i][j] - mean[j];
              stddev[j] += diff * diff;
          }
      }

      DATA_TYPE sqrt_n = SQRT_FUN(float_n);
      DATA_TYPE divisor[CHUNK];

      // Post-process the standard deviation safely and set up divisors
      for (int j = jj; j < j_max; j++) {
          stddev[j] /= float_n;
          stddev[j] = SQRT_FUN(stddev[j]);
          stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
          divisor[j - jj] = sqrt_n * stddev[j];
      }

      // Center and reduce data for the chunk
      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              data[i][j] = (data[i][j] - mean[j]) / divisor[j - jj];
          }
      }
  }

#undef CHUNK

  /* Phase 2: Calculate the m * m correlation matrix.
     Start by Initializing the correlation matrix appropriately. */
  #pragma omp parallel for schedule(dynamic, 16)
  for (int i = 0; i < _PB_M; i++) {
      corr[i][i] = SCALAR_VAL(1.0);
      for (int j = i + 1; j < _PB_M; j++) {
          corr[i][j] = SCALAR_VAL(0.0);
      }
  }

#define B_I 64
#define B_J 256
#define B_K 256

  /* Cache-blocked matrix multiplication C = D^T D 
     Designed to strictly maintain L1d cache integrity for active RMW targets. */
  #pragma omp parallel for schedule(dynamic)
  for (int jj = 0; jj < _PB_M; jj += B_J) {
      int j_max = (jj + B_J < _PB_M) ? jj + B_J : _PB_M;

      for (int kk = 0; kk < _PB_N; kk += B_K) {
          int k_max = (kk + B_K < _PB_N) ? kk + B_K : _PB_N;

          for (int ii = 0; ii < _PB_M - 1; ii += B_I) {
              if (ii >= j_max) continue; // Completely out of upper triangular range

              int i_max = (ii + B_I < _PB_M - 1) ? ii + B_I : _PB_M - 1;
              if (i_max > j_max - 1) i_max = j_max - 1; // Clamp bounds

              for (int i = ii; i < i_max; i++) {
                  int j_start = (jj > i + 1) ? jj : i + 1;

                  for (int k = kk; k < k_max; k++) {
                      DATA_TYPE d_ki = data[k][i];

                      #pragma GCC ivdep
                      #pragma GCC unroll 4
                      for (int j = j_start; j < j_max; j++) {
                          corr[i][j] += d_ki * data[k][j];
                      }
                  }
              }
          }
      }
  }

#undef B_I
#undef B_J
#undef B_K

  /* Reflect bounds to symmetrize the lower triangle of the correlation matrix */
  #pragma omp parallel for schedule(dynamic, 16)
  for (int i = 0; i < _PB_M - 1; i++) {
      for (int j = i + 1; j < _PB_M; j++) {
          corr[j][i] = corr[i][j];
