/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  DATA_TYPE eps = SCALAR_VAL(0.1);
  DATA_TYPE sqrt_n = SQRT_FUN(float_n);

#pragma scop

  /* Phase 1: Compute mean, stddev, and center data.
     We tile the loop over columns (j) to maximize cache locality 
     and allow perfect parallelization without reductions. */
  #define TILE_C 256
  int num_tiles_c = (_PB_M + TILE_C - 1) / TILE_C;

  #pragma omp parallel for schedule(static)
  for (int t_j = 0; t_j < num_tiles_c; t_j++) {
      int jj = t_j * TILE_C;
      int j_max = jj + TILE_C < _PB_M ? jj + TILE_C : _PB_M;

      // 1. Compute mean
      for (int j = jj; j < j_max; j++) {
          mean[j] = SCALAR_VAL(0.0);
      }
      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              mean[j] += data[i][j];
          }
      }
      for (int j = jj; j < j_max; j++) {
          mean[j] /= float_n;
      }

      // 2. Compute stddev
      for (int j = jj; j < j_max; j++) {
          stddev[j] = SCALAR_VAL(0.0);
      }
      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              DATA_TYPE diff = data[i][j] - mean[j];
              stddev[j] += diff * diff;
          }
      }
      for (int j = jj; j < j_max; j++) {
          stddev[j] /= float_n;
          stddev[j] = SQRT_FUN(stddev[j]);
          stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];
      }

      // 3. Center and reduce data sequentially (precompute constants)
      DATA_TYPE factors[TILE_C];
      for (int j = jj; j < j_max; j++) {
          factors[j - jj] = SCALAR_VAL(1.0) / (sqrt_n * stddev[j]);
      }
      for (int i = 0; i < _PB_N; i++) {
          #pragma GCC ivdep
          for (int j = jj; j < j_max; j++) {
              data[i][j] = (data[i][j] - mean[j]) * factors[j - jj];
          }
      }
  }

  /* Phase 2: Calculate the upper triangle of the correlation matrix.
     We use a 2D tiled approach over i and j, keeping the correlation 
     tile within the inner limits of the L1 cache. */
  #define TILE_I 64
  #define TILE_J 64
  int num_tiles_i = (_PB_M + TILE_I - 1) / TILE_I;
  int num_tiles_j = (_PB_M + TILE_J - 1) / TILE_J;

  #pragma omp parallel for collapse(2) schedule(dynamic)
  for (int t_i = 0; t_i < num_tiles_i; t_i++) {
      for (int t_j = 0; t_j < num_tiles_j; t_j++) {
          int ii = t_i * TILE_I;
          int jj = t_j * TILE_J;

          if (jj >= ii) {
              int i_max = ii + TILE_I < _PB_M ? ii + TILE_I : _PB_M;
              int j_max = jj + TILE_J < _PB_M ? jj + TILE_J : _PB_M;

              // Initialize correlation tile
              for (int i = ii; i < i_max; i++) {
                  int j_start = (jj > i + 1) ? jj : i + 1;
                  #pragma GCC ivdep
                  for (int j = j_start; j < j_max; j++) {
                      corr[i][j] = SCALAR_VAL(0.0);
                  }
              }

              // Compute correlation tile with optimal stride-1 mapping behavior
              for (int k = 0; k < _PB_N; k++) {
                  for (int i = ii; i < i_max; i++) {
                      DATA_TYPE d_ki = data[k][i];
                      int j_start = (jj > i + 1) ? jj : i + 1;

                      #pragma GCC ivdep
                      for (int j = j_start; j < j_max; j++) {
                          corr[i][j] += d_ki * data[k][j];
                      }
                  }
              }
          }
      }
  }

  /* Phase 3: Mirror the upper triangle to the lower triangle 
     and set the diagonal to 1.0. Parallelized by row (j) to prevent 
     false sharing inside cache-lines. */
  #pragma omp parallel for schedule(static)
  for (int j = 0; j < _PB_M; j++) {
      for (int i = 0; i < j; i++) {
          corr[j][i] = corr[i][j];
      }
      corr[j][j] = SCALAR_VAL(1.0);
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}
